   "goal": "I can tell when someone is hinting or asking without asking.",
   "slpNotes": "People often ask for things indirectly (“I forgot my pencil…”, “Are you using that?”, “It’s cold in here”). Students who take language literally may answer the words and miss the request. Practice turning each hint into the real ask, then into a helpful reply. When unsure, the student can check: “Do you want me to…?”\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
