   "goal": "I can think about what a text means and ask when I’m not sure.",
   "slpNotes": "Texts have no voice, face, or body, so short replies (“k,” “fine.”), all caps, and late replies are easy to misread. Teach that the same text can mean different things, and that the reader often fills in the worst meaning. Practice a friendly check-in text. Emoji can add some tone but can still be misread.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
