   "title": "Picking the best guess",
   "unit": "SCOPE Unit 3: Reading Between the Lines",
   "program": "SCOPE",
   "skill": "Choosing the meaning that fits the most clues",
   "goal": "I can pick the guess that fits the most clues and change it if I need to.",
   "slpNotes": "Students list several possible meanings, then test each against the clues. The best guess is the one that fits the most clues, not the first idea or the scariest one. Model staying flexible: when a new clue appears, update the guess. A quick tally (“How many clues fit?”) can help.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
