   "id": "scope-25",
   "number": 25,
   "title": "That happened to me too",
   "unit": "SCOPE Unit 4: Relating Experiences",
   "program": "SCOPE",
   "skill": "Making a short, related connection",
   "goal": "I can share a short, related story and turn back to my friend.",
   "slpNotes": "Teach the \"connect and turn back\" move: one or two related sentences about yourself, then a question or comment that puts the focus back on the speaker. Common errors are off-topic stories, long stories, and one-upping (\"Mine was better\"). Model a too-long version and a just-right version, and count sentences on your fingers. Keep personal open responses to safe topics such as school, hobbies, games, sports, pets, food, and weekends.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
