   "goal": "I can use my own experience to guess, then ask to check.",
   "slpNotes": "Teach a two-step move: use a similar experience to make a guess about how someone might feel, then check the guess by asking, because the other person may feel differently. Stress words like \"might\" and \"maybe.\" If the student says \"They must feel just like I did,\" prompt with \"How could you check?\"\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
