   "goal": "I can tell when it is a good time to share my story.",
   "slpNotes": "Focus on reading the moment before sharing: Is someone upset? Is the teacher talking? Is a friend sharing big news? In those moments, listen first, then save the story or keep it to one sentence. Contrast a story that fits with one that takes over. A short connection can comfort an upset friend, but only after listening and only if the focus stays on them.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
