   "skill": "Finding the real problem",
   "goal": "I can find the real problem, not just my first feeling.",
   "slpNotes": "Students often name their first reaction (“Omar is laughing at me!”) or a side issue as the problem. Teach one guiding question: “What needs to be fixed?” The real problem is usually something an action can fix. Model thinking aloud: “My first feeling is ___, but the real problem is ___.”\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
