   "skill": "Sizing problems and matching reactions",
   "goal": "I can tell how big a problem is and react to match.",
   "slpNotes": "Use three sizes: small (I can fix it myself), medium (I need some help from a friend or adult), and big (someone is hurt or unsafe; get an adult right away). Talk about matching the size of the reaction to the size of the problem. People can size the same problem a little differently, so accept small or medium when the student gives a reason. For any big problem, the answer is always to get an adult.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
