   "slpNotes": "Teach three clarifying questions: “Do you mean…?”, “Are you joking?”, and “Can you say that another way?” Talk about timing: wait for a pause, raise a hand in class, or ask after. Model the same question in a calm, curious voice and then in a rude voice so the student hears how tone changes the message.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.\n\nVideo search ideas: asking clarifying questions social skills; how to ask for clarification middle school",
