   "slpNotes": "Teach four repair steps: notice it, say sorry if needed, explain, and make a plan. Point out that a mix-up often is no one’s fault; “Sorry for the mix-up” can mean sorry it happened, not “I was bad.” Role-play the Engage step with the student as Omar and you as Mom.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.\n\nVideo search ideas: fixing misunderstandings social skills video; repairing a friendship after a misunderstanding",
